update public.questions set subject = 'Geography', topic = 'Indian Physiography, Climate & Regions', type = 'statement_based', difficulty = 'medium', body = 'Kuttanad in Kerala is one of the few places in the world where rice is grown below mean sea level. Consider the following statements about farming there:', body_hi = 'केरल का कुट्टनाड दुनिया के उन गिने-चुने स्थानों में है जहाँ माध्य समुद्र तल से नीचे धान उगाया जाता है। वहाँ की खेती के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct; both follow from farming below sea level. The polders of Kuttanad, reclaimed from the backwaters, sit one to two metres below sea level, so water has to be kept out by bunds and pumped off before each crop. In the dry season, when river flow falls, the sea pushes salt water up the backwaters; the Thanneermukkom barrier, built in the 1970s, is closed then to protect the paddy. Statement 3 is wrong: Kuttanad''s soils are waterlogged, acidic and rich in peat and organic matter (the ''kari'' soils). They are dark, which is the trap, but they have nothing to do with the regur of the Deccan lavas. The FAO recognises the system as a Globally Important Agricultural Heritage System.', explanation_hi = 'कथन 1 और 2 सही हैं; दोनों समुद्र तल से नीचे खेती का ही परिणाम हैं। पश्च जल (backwaters) से प्राप्त कुट्टनाड के खेत समुद्र तल से एक-दो मीटर नीचे हैं, इसलिए पानी को मेड़ों से बाहर रखना और हर फ़सल से पहले पंप से निकालना पड़ता है। शुष्क मौसम में जब नदियों का प्रवाह घटता है, तो समुद्र खारा पानी पश्च जल में ऊपर धकेलता है; 1970 के दशक में बना थन्नीरमुक्कम अवरोध तब धान की रक्षा के लिए बंद किया जाता है। कथन 3 गलत है: कुट्टनाड की मिट्टी जलभराव वाली, अम्लीय और पीट तथा जैविक पदार्थ से भरपूर (''करी'' मिट्टी) है। यह गहरे रंग की है, यही जाल है, पर इसका दक्कन के लावा से बनी रेगुर से कोई संबंध नहीं। FAO इस प्रणाली को विश्व स्तर पर महत्वपूर्ण कृषि विरासत प्रणाली (GIAHS) मानता है।', concept_group_id = 'igeo-kuttanad-bagar-teri', source_citation = 'NCERT Class XI, India: Physical Environment -- Structure and Physiography; FAO -- Globally Important Agricultural Heritage Systems (Kuttanad).', question_data = '{"statements": ["Its fields are ringed by dykes and must be drained by pumping before sowing.", "A barrier across Vembanad lake at Thanneermukkom was built to keep sea water out of the paddy fields in the dry season.", "Its soils are mainly the black regur formed from Deccan lava."], "statements_hi": ["इसके खेत तटबंधों से घिरे हैं और बुवाई से पहले पंप से उनका पानी निकालना पड़ता है।", "शुष्क मौसम में धान के खेतों से समुद्री जल को दूर रखने के लिए थन्नीरमुक्कम में वेम्बनाड झील पर एक अवरोध बनाया गया।", "इसकी मिट्टी मुख्य रूप से दक्कन के लावा से बनी काली रेगुर मिट्टी है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'igeo-kuttanad-bagar-teri' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Indian Physiography, Climate & Regions', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. The Mishmi Hills rise in eastern Arunachal Pradesh, around the Dibang and Lohit valleys, where the Himalaya bends south. The Dafla Hills are also in Arunachal Pradesh, in its western-central part, named after the Nyishi people once called Daflas; Nagaland''s hills belong to the Patkai-Naga system along the Myanmar border.', explanation_hi = 'केवल कथन 1 सही है। मिशमी पहाड़ियाँ पूर्वी अरुणाचल प्रदेश में दिबांग और लोहित घाटियों के आसपास उठती हैं, जहाँ हिमालय दक्षिण की ओर मुड़ता है। डफला पहाड़ियाँ भी अरुणाचल प्रदेश में, उसके पश्चिम-मध्य भाग में हैं, जिनका नाम उन न्यिशी लोगों पर पड़ा जिन्हें पहले डफला कहा जाता था; नागालैंड की पहाड़ियाँ म्यांमार सीमा के साथ पटकाई-नागा श्रेणी का भाग हैं।', concept_group_id = 'igeo-mishmi-dafla-hills-easy', source_citation = 'NCERT Class XI, India: Physical Environment -- Structure and Physiography; Oxford School Atlas.', question_data = '{"statements": ["The Mishmi Hills lie in Arunachal Pradesh.", "The Dafla Hills lie in Nagaland."], "statements_hi": ["मिशमी पहाड़ियाँ अरुणाचल प्रदेश में हैं।", "डफला पहाड़ियाँ नागालैंड में हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'igeo-mishmi-dafla-hills-easy' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'World Regions, Water Bodies & Places', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of waterfalls and the countries where they are located:', body_hi = 'जलप्रपातों और उन देशों के निम्नलिखित युग्मों पर विचार कीजिए जहाँ वे स्थित हैं:', explanation = 'Only the first two pairs are correct. Angel Falls, in Venezuela''s Canaima National Park, is the world''s highest uninterrupted waterfall, at about 979 m. The Iguazu Falls, a chain of some 275 falls on the Iguazu river, lie on the border of Argentina and Brazil. Tugela Falls is in South Africa''s Drakensberg range, in KwaZulu-Natal, and is often ranked second in height. Kaieteur Falls, on the Potaro river, is in Guyana and is known for its great single drop.', explanation_hi = 'केवल पहले दो युग्म सही हैं। वेनेज़ुएला के कनाइमा राष्ट्रीय उद्यान का एंजेल जलप्रपात लगभग 979 मीटर के साथ दुनिया का सबसे ऊँचा अविच्छिन्न जलप्रपात है। इगुआज़ू नदी पर लगभग 275 जलप्रपातों की शृंखला, इगुआज़ू जलप्रपात, अर्जेंटीना और ब्राज़ील की सीमा पर है। तुगेला जलप्रपात दक्षिण अफ़्रीका के क्वाज़ुलु-नटाल में ड्रैकेन्सबर्ग पर्वत में है और ऊँचाई में प्रायः दूसरे स्थान पर गिना जाता है। पोटारो नदी पर काइएतूर जलप्रपात गुयाना में है और अपनी विशाल एकल धार के लिए प्रसिद्ध है।', concept_group_id = 'geo-waterfalls-countries-pairs', source_citation = 'Oxford School Atlas -- South America and Africa.', question_data = '{"list_1": ["1. Angel Falls", "2. Iguazu Falls", "3. Tugela Falls", "4. Kaieteur Falls"], "list_1_hi": ["1. एंजेल जलप्रपात", "2. इगुआज़ू जलप्रपात", "3. तुगेला जलप्रपात", "4. काइएतूर जलप्रपात"], "list_2": ["Venezuela", "Argentina and Brazil", "Tanzania", "Suriname"], "list_2_hi": ["वेनेज़ुएला", "अर्जेंटीना और ब्राज़ील", "तंज़ानिया", "सूरीनाम"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'geo-waterfalls-countries-pairs' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'World Regions, Water Bodies & Places', type = 'mcq', difficulty = 'hard', body = 'The Sahel, which stretches across Africa from Senegal to Sudan, is among the regions of the world most prone to drought and land degradation. Which one of the following best explains this?', body_hi = 'सेनेगल से सूडान तक अफ़्रीका में फैला साहेल दुनिया के उन क्षेत्रों में है जो सूखे और भूमि क्षरण के प्रति सबसे अधिक संवेदनशील हैं। निम्नलिखित में से कौन-सा इसकी सबसे सही व्याख्या करता है?', explanation = 'The Sahel lies where the Intertropical Convergence Zone reaches its northern limit in the northern summer. In a good year it brings three or four months of rain; in a poor year it stalls further south. Because so much depends on one short season, rainfall swings widely from year to year, and droughts such as those of the 1970s and 1980s, together with overgrazing and the clearing of vegetation, degrade the land. The cold-current explanation fits west-coast deserts such as the Namib and the Atacama, and the Atlas rain shadow concerns North-West Africa. The doldrums, far from preventing clouds, bring heavy convectional rain near the Equator. The African Union''s Great Green Wall initiative aims to restore land across the belt.', explanation_hi = 'साहेल वहाँ है जहाँ अंतर-उष्णकटिबंधीय अभिसरण क्षेत्र (ITCZ) उत्तरी गर्मियों में अपनी उत्तरी सीमा तक पहुँचता है। अच्छे वर्ष में यह तीन-चार महीने वर्षा लाता है; कमज़ोर वर्ष में यह और दक्षिण में ही रुक जाता है। इतना कुछ एक छोटी ऋतु पर निर्भर होने से वर्षा वर्ष-दर-वर्ष बहुत बदलती है, और 1970-80 के दशकों जैसे सूखे, अति-चराई और वनस्पति की कटाई के साथ मिलकर भूमि का क्षरण करते हैं। ठंडी धारा वाली व्याख्या नामीब और अटाकामा जैसे पश्चिमी तट के मरुस्थलों पर लागू होती है, और एटलस की वृष्टि-छाया उत्तर-पश्चिम अफ़्रीका से जुड़ी है। डोलड्रम्स बादलों को रोकते नहीं, बल्कि विषुवत रेखा के पास भारी संवहनीय वर्षा लाते हैं। अफ़्रीकी संघ की ''ग्रेट ग्रीन वॉल'' पहल इस पट्टी में भूमि को फिर से उपजाऊ बनाने का लक्ष्य रखती है।', concept_group_id = 'geo-sahel-drought-itcz', source_citation = 'NCERT Class XI, Fundamentals of Physical Geography -- Atmospheric Circulation and Weather Systems; Oxford School Atlas -- Africa; UNCCD -- Great Green Wall.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "It lies on the western margin of the continent beside a cold current, which keeps the air stable and dry through the year", "body_hi": "यह महाद्वीप के पश्चिमी किनारे पर एक ठंडी धारा के पास है, जो वायु को वर्ष भर स्थिर और शुष्क रखती है", "isCorrect": false}, {"id": "b", "body": "It lies in the rain shadow of the Atlas Mountains, which block the moist westerlies coming in from the Atlantic", "body_hi": "यह एटलस पर्वतों के वृष्टि-छाया क्षेत्र में है, जो अटलांटिक से आने वाली नम पछुआ पवनों को रोकते हैं", "isCorrect": false}, {"id": "c", "body": "It is a semi-arid belt between the Sahara and the savanna, where rain comes in one short season and varies greatly from year to year", "body_hi": "यह सहारा और सवाना के बीच की अर्ध-शुष्क पट्टी है, जहाँ वर्षा एक छोटी ऋतु में होती है और वर्ष-दर-वर्ष बहुत बदलती है", "isCorrect": true}, {"id": "d", "body": "It lies beneath the doldrums, where calm air and steady rising currents prevent clouds from forming over the land for most months of the year", "body_hi": "यह डोलड्रम्स के नीचे है, जहाँ शांत वायु और लगातार ऊपर उठती धाराएँ वर्ष के अधिकांश महीनों में भूमि पर बादल नहीं बनने देतीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'geo-alliance-of-sahel-states' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Climatology & Biomes', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the cooling and warming of moving air:', body_hi = 'गतिशील वायु के ठंडे और गर्म होने के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct. A rising parcel of air expands into lower pressure and does work on its surroundings, so its temperature falls even though no heat leaves it -- adiabatic cooling, at about 9.8 °C per km for dry air. Once the air is saturated, condensation releases latent heat, so the wet adiabatic rate is lower, roughly 4-7 °C per km depending on moisture. Sinking air does the reverse: compression warms it, clouds evaporate, and so anticyclones and the subtropical highs bring clear, dry weather.', explanation_hi = 'तीनों कथन सही हैं। ऊपर उठता वायु-पिंड कम दाब में फैलता है और अपने परिवेश पर कार्य करता है, इसलिए उसका तापमान गिरता है जबकि कोई ऊष्मा बाहर नहीं जाती; यह रुद्धोष्म (adiabatic) शीतलन है, जो शुष्क वायु के लिए लगभग 9.8 °C प्रति किमी होता है। वायु संतृप्त होने पर संघनन से गुप्त ऊष्मा मुक्त होती है, इसलिए आर्द्र रुद्धोष्म दर कम, नमी के अनुसार लगभग 4-7 °C प्रति किमी होती है। नीचे उतरती वायु में उल्टा होता है: संपीड़न से वह गर्म होती है, बादल वाष्पित हो जाते हैं, और इसलिए प्रतिचक्रवात तथा उपोष्ण उच्च दाब क्षेत्र साफ़ और शुष्क मौसम लाते हैं।', concept_group_id = 'geo-adiabatic-dry-wet-subsidence', source_citation = 'NCERT Class XI, Fundamentals of Physical Geography -- Water in the Atmosphere; Atmospheric Circulation and Weather Systems.', question_data = '{"statements": ["Air that rises cools because it expands under lower pressure, even though it loses no heat to its surroundings.", "Rising saturated air cools more slowly than rising dry air, because condensation releases latent heat.", "Sinking air warms as it is compressed, which is why areas under high pressure usually have clear skies."], "statements_hi": ["ऊपर उठती वायु ठंडी होती है क्योंकि कम दाब में वह फैलती है, भले ही वह अपने परिवेश को कोई ऊष्मा न खोए।", "ऊपर उठती संतृप्त वायु शुष्क वायु की तुलना में धीरे ठंडी होती है, क्योंकि संघनन से गुप्त ऊष्मा मुक्त होती है।", "नीचे उतरती वायु संपीड़ित होने से गर्म होती है, इसी कारण उच्च दाब वाले क्षेत्रों में प्रायः आकाश साफ़ रहता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'geo-adiabatic-dry-wet-subsidence' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Climatology & Biomes', type = 'assertion_reason', difficulty = 'medium', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct and Statement-II explains Statement-I. Normally the trade winds pile warm water in the western Pacific, where air rises, while cool water and sinking air lie off South America. In El Nino years the trades weaken, warm water spreads east and the rising limb of the Walker circulation moves toward the central and eastern Pacific; the compensating sinking air over the Indian Ocean and South Asia suppresses rain. The link is strong but not fixed -- 1997 brought a strong El Nino and a normal monsoon -- because conditions in the Indian Ocean and over Eurasia also shape the season.', explanation_hi = 'दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। सामान्यतः व्यापारिक पवनें गर्म जल को पश्चिमी प्रशांत में इकट्ठा करती हैं, जहाँ वायु ऊपर उठती है, जबकि दक्षिण अमेरिका के पास ठंडा जल और नीचे उतरती वायु रहती है। अल नीनो वर्षों में व्यापारिक पवनें कमज़ोर पड़ती हैं, गर्म जल पूर्व की ओर फैलता है और वॉकर परिसंचरण की ऊपर उठती भुजा मध्य और पूर्वी प्रशांत की ओर चली जाती है; इसकी भरपाई में हिंद महासागर और दक्षिण एशिया के ऊपर नीचे उतरती वायु वर्षा को दबा देती है। यह संबंध मज़बूत है पर निश्चित नहीं; 1997 में प्रबल अल नीनो के बावजूद मानसून सामान्य रहा, क्योंकि हिंद महासागर और यूरेशिया की परिस्थितियाँ भी इस ऋतु को प्रभावित करती हैं।', concept_group_id = 'geo-el-nino-walker-monsoon', source_citation = 'NCERT Class XI, Fundamentals of Physical Geography -- Atmospheric Circulation and Weather Systems; India Meteorological Department -- monsoon and ENSO.', question_data = '{"assertion": "Years of El Nino are often marked by a weaker than normal south-west monsoon in India.", "assertion_hi": "अल नीनो वाले वर्षों में भारत में दक्षिण-पश्चिम मानसून प्रायः सामान्य से कमज़ोर रहता है।", "reason": "During El Nino, the warm water and rising air of the Walker circulation shift eastward across the Pacific, leaving sinking air over the Indian region.", "reason_hi": "अल नीनो के दौरान वॉकर परिसंचरण का गर्म जल और ऊपर उठती वायु प्रशांत महासागर में पूर्व की ओर खिसक जाते हैं, और भारतीय क्षेत्र के ऊपर नीचे उतरती वायु रह जाती है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'geo-el-nino-walker-monsoon' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Resources: Minerals, Energy & Agriculture', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about mining in India:', body_hi = 'भारत में खनन के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Sukinda, in Jajpur district, accounts for most of India''s chromite, the ore of chromium; the heaps of mine waste have also made it one of the country''s worst hot-spots of hexavalent chromium pollution. Rampura Agucha in Bhilwara district is a giant zinc-lead deposit mined by Hindustan Zinc. Statement 3 is wrong: the Kolar Gold Fields, among the deepest mines in the world, closed in 2001 when costs outran output; most of India''s mined gold now comes from the Hutti mines, also in Karnataka.', explanation_hi = 'कथन 1 और 2 सही हैं। जाजपुर ज़िले का सुकिंडा भारत के अधिकांश क्रोमाइट, यानी क्रोमियम के अयस्क, का स्रोत है; खदानों के कचरे के ढेरों ने इसे हेक्सावैलेंट क्रोमियम प्रदूषण के देश के सबसे बुरे केंद्रों में भी बना दिया है। भीलवाड़ा ज़िले का रामपुरा अगुचा जस्ता-सीसा का विशाल भंडार है, जिसका खनन हिंदुस्तान ज़िंक करता है। कथन 3 गलत है: दुनिया की सबसे गहरी खदानों में गिना जाने वाला कोलार स्वर्ण क्षेत्र 2001 में बंद हो गया जब लागत उत्पादन से अधिक हो गई; अब भारत का अधिकांश खनित सोना कर्नाटक की ही हट्टी खदानों से आता है।', concept_group_id = 'res-sukinda-rampura-kolar', source_citation = 'Indian Bureau of Mines -- Indian Minerals Yearbook; NCERT Class XII, India: People and Economy -- Mineral and Energy Resources.', question_data = '{"statements": ["The Sukinda valley in Odisha holds the bulk of India''s chromite reserves.", "Rampura Agucha in Rajasthan is one of the world''s largest zinc-lead mines.", "The Kolar Gold Fields in Karnataka remain India''s largest producer of gold."], "statements_hi": ["ओडिशा की सुकिंडा घाटी में भारत के क्रोमाइट भंडार का अधिकांश भाग है।", "राजस्थान का रामपुरा अगुचा दुनिया की सबसे बड़ी जस्ता-सीसा खदानों में से एक है।", "कर्नाटक का कोलार स्वर्ण क्षेत्र आज भी भारत का सबसे बड़ा सोना उत्पादक है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'res-sukinda-rampura-kolar' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Transport, Ports & Human Geography', type = 'mcq', difficulty = 'medium', body = 'The Bogibeel rail-cum-road bridge, opened in 2018 near Dibrugarh, is often described as strategically important. Which one of the following best explains why?', body_hi = '2018 में डिब्रूगढ़ के पास खुले बोगीबील रेल-सह-सड़क पुल को प्रायः सामरिक रूप से महत्वपूर्ण बताया जाता है। निम्नलिखित में से कौन-सा इसका सबसे सही कारण है?', explanation = 'Bogibeel spans the Brahmaputra between Dibrugarh district on the south bank and Dhemaji on the north bank, where crossing used to mean long ferry trips or detours of hundreds of kilometres. With a double railway line below a three-lane road, it lets troops and supplies move quickly toward the Arunachal Pradesh frontier, which is why it is called strategic; it is also India''s longest rail-cum-road bridge, at about 4.9 km. It has nothing to do with the Siliguri corridor, the oil pipelines or a land route to Myanmar.', explanation_hi = 'बोगीबील दक्षिणी तट पर डिब्रूगढ़ ज़िले और उत्तरी तट पर धेमाजी के बीच ब्रह्मपुत्र पर बना है, जहाँ पहले पार जाने का अर्थ था लंबी नौका-यात्रा या सैकड़ों किलोमीटर का चक्कर। तीन लेन की सड़क के नीचे दोहरी रेल लाइन के साथ यह सैनिकों और रसद को अरुणाचल प्रदेश की सीमा की ओर तेज़ी से पहुँचाने देता है, इसीलिए इसे सामरिक कहा जाता है; यह लगभग 4.9 किमी के साथ भारत का सबसे लंबा रेल-सह-सड़क पुल भी है। इसका सिलीगुड़ी गलियारे, तेल पाइपलाइनों या म्यांमार के स्थल मार्ग से कोई संबंध नहीं है।', concept_group_id = 'tr-bogibeel-brahmaputra', source_citation = 'Ministry of Railways -- Bogibeel rail-cum-road bridge; Northeast Frontier Railway.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "It gives an all-weather road and rail link from the south bank of the Brahmaputra to the north bank and onward to the Arunachal border", "body_hi": "यह ब्रह्मपुत्र के दक्षिणी तट से उत्तरी तट और आगे अरुणाचल सीमा तक हर मौसम में चलने वाला सड़क और रेल संपर्क देता है", "isCorrect": true}, {"id": "b", "body": "It completes the direct road link between the Siliguri corridor and the southern border towns of Bhutan", "body_hi": "यह सिलीगुड़ी गलियारे और भूटान के दक्षिणी सीमावर्ती क़स्बों के बीच सीधा सड़क संपर्क पूरा करता है", "isCorrect": false}, {"id": "c", "body": "It carries the main crude-oil pipeline from the Assam oilfields across the river to the Barauni refinery", "body_hi": "यह असम के तेल क्षेत्रों से नदी के पार बरौनी रिफ़ाइनरी तक मुख्य कच्चे तेल की पाइपलाइन ले जाता है", "isCorrect": false}, {"id": "d", "body": "It links Assam with Myanmar across the Patkai hills, giving India a direct land route to the markets of South-East Asia for the first time", "body_hi": "यह पटकाई पहाड़ियों के पार असम को म्यांमार से जोड़ता है, जिससे भारत को पहली बार दक्षिण-पूर्व एशिया के बाज़ारों तक सीधा स्थल मार्ग मिलता है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'tr-bogibeel-brahmaputra' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Indian Rivers, Lakes & Wetlands', type = 'statement_based', difficulty = 'hard', body = 'Consider the following statements about dams and the rivers they are built on:', body_hi = 'बाँधों और उन नदियों के बारे में निम्नलिखित कथनों पर विचार कीजिए जिन पर वे बने हैं:', explanation = 'Only statement 1 is correct. Hirakud, near Sambalpur in Odisha (completed in 1957), is one of the longest earthen dams in the world, built to control the Mahanadi''s floods and irrigate its delta. Statement 2 is wrong: Almatti, in the Vijayapura district of Karnataka, is on the Krishna and forms the main reservoir of the Upper Krishna Project. Statement 3 is wrong: Ukai, in Gujarat, is on the Tapi, upstream of Surat.', explanation_hi = 'केवल कथन 1 सही है। ओडिशा में संबलपुर के पास हीराकुड (1957 में पूर्ण) दुनिया के सबसे लंबे मिट्टी के बाँधों में से है, जो महानदी की बाढ़ रोकने और उसके डेल्टा की सिंचाई के लिए बना। कथन 2 गलत है: कर्नाटक के विजयपुरा ज़िले का अलमट्टी बाँध कृष्णा पर है और ऊपरी कृष्णा परियोजना का मुख्य जलाशय बनाता है। कथन 3 गलत है: गुजरात का उकाई बाँध सूरत से ऊपर की ओर तापी पर है।', concept_group_id = 'irv-dams-hirakud-almatti-ukai', source_citation = 'NCERT Class XI, India: Physical Environment -- Drainage System; Central Water Commission -- National Register of Large Dams.', question_data = '{"statements": ["The Hirakud dam is built across the Mahanadi.", "The Almatti dam is built across the Godavari.", "The Ukai dam is built across the Narmada."], "statements_hi": ["हीराकुड बाँध महानदी पर बना है।", "अलमट्टी बाँध गोदावरी पर बना है।", "उकाई बाँध नर्मदा पर बना है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'irv-dams-hirakud-almatti-ukai' returning concept_group_id;
update public.questions set subject = 'Geography', topic = 'Geomorphology & Earth''s Interior', type = 'assertion_reason', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct, but Statement-II does not explain Statement-I. The peeling, called exfoliation or onion-skin weathering, comes from the wide gap between day and night temperatures: the outer shell of a rock heats and expands by day and cools and contracts by night more than its interior, until it loosens and flakes away; the release of pressure on rock exposed by erosion helps too. Low rainfall is simply another feature of deserts, not the cause of the peeling.', explanation_hi = 'दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। इस परत-उतरने को अपशल्कन (exfoliation) या प्याज़-छिलका अपक्षय कहते हैं; यह दिन और रात के तापमान के बड़े अंतर से होता है: चट्टान का बाहरी खोल दिन में गर्म होकर फैलता है और रात में भीतरी भाग से अधिक ठंडा होकर सिकुड़ता है, जब तक वह ढीला होकर उतर न जाए; अपरदन से खुली चट्टान पर दाब कम होने से भी यह होता है। कम वर्षा मरुस्थल की एक अन्य विशेषता मात्र है, परत उतरने का कारण नहीं।', concept_group_id = 'geo-exfoliation-diurnal-range', source_citation = 'NCERT Class XI, Fundamentals of Physical Geography -- Geomorphic Processes.', question_data = '{"assertion": "In hot deserts, the outer layers of exposed rocks often peel off in curved sheets.", "assertion_hi": "गर्म मरुस्थलों में खुली चट्टानों की बाहरी परतें प्रायः घुमावदार परतों के रूप में उतर जाती हैं।", "reason": "Hot deserts receive very little rainfall in a year.", "reason_hi": "गर्म मरुस्थलों में वर्ष भर में बहुत कम वर्षा होती है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'geo-exfoliation-diurnal-range' returning concept_group_id;
commit;
